CREATE OR REPLACE FUNCTION public.validate_card_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.lists WHERE id=NEW.list_id AND board_id=NEW.board_id) THEN RAISE EXCEPTION 'List does not belong to destination board'; END IF; IF TG_TABLE_NAME='card_mirrors' AND TG_OP='UPDATE' AND NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'A mirror cannot change its source card'; END IF; IF TG_TABLE_NAME='cards' AND TG_OP='UPDATE' AND NEW.board_id<>OLD.board_id AND (NOT public.owns_board(OLD.board_id) OR NOT public.can_access_board(NEW.board_id)) THEN RAISE EXCEPTION 'Only the source board owner can move a card between boards'; END IF; RETURN NEW; END $$;
DROP TRIGGER validate_mirrors_location ON public.card_mirrors;
CREATE TRIGGER validate_mirrors_location BEFORE INSERT OR UPDATE ON public.card_mirrors FOR EACH ROW EXECUTE FUNCTION public.validate_card_location();
CREATE OR REPLACE FUNCTION public.can_edit_label(_label_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.labels l WHERE l.id=_label_id AND public.can_access_board(l.board_id)) OR EXISTS(SELECT 1 FROM public.card_labels cl WHERE cl.label_id=_label_id AND public.can_access_card(cl.card_id)) $$;
CREATE POLICY "mirror collaborators edit shared label definitions" ON public.labels FOR UPDATE TO authenticated USING(public.can_edit_label(id)) WITH CHECK(public.can_edit_label(id));
REVOKE ALL ON FUNCTION public.can_edit_label(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_edit_label(uuid) TO authenticated,service_role;